DO $browser_release$
DECLARE ns OID; owner_id OID; target OID; signature TEXT; fn RECORD;
BEGIN
 IF current_user <> session_user OR current_user <> 'pscale_api_exl4hoyn673g'
 THEN RAISE EXCEPTION 'Browser release requires exact bound owner session'; END IF;
 SELECT n.oid,n.nspowner INTO ns,owner_id FROM pg_catalog.pg_namespace n
 JOIN pg_catalog.pg_class u ON u.relnamespace=n.oid AND u.relname='users'
 JOIN pg_catalog.pg_class p ON p.relnamespace=n.oid AND p.relname='participation_owners'
 WHERE n.nspname='api_next' AND n.nspowner=u.relowner AND n.nspowner=p.relowner
 AND pg_catalog.pg_get_userbyid(n.nspowner)='pscale_api_exl4hoyn673g';
 IF ns IS NULL THEN RAISE EXCEPTION 'Browser release schema owner differs'; END IF;
 SELECT oid INTO target FROM pg_catalog.pg_roles WHERE rolname='pscale_api_4bxas7gq43a4' AND rolcanlogin
 AND NOT(rolsuper OR rolbypassrls OR rolcreatedb OR rolcreaterole OR rolreplication);
 IF target IS NULL OR pg_catalog.pg_has_role(target,owner_id,'MEMBER')
 OR NOT pg_catalog.has_schema_privilege(target,ns,'USAGE') OR pg_catalog.has_schema_privilege(target,ns,'CREATE')
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_roles inherited WHERE inherited.oid<>target
 AND pg_catalog.pg_has_role(target,inherited.oid,'MEMBER')
 AND (inherited.rolsuper OR inherited.rolbypassrls OR inherited.rolcreatedb OR inherited.rolcreaterole OR inherited.rolreplication))
 THEN RAISE EXCEPTION 'Browser release runtime role differs'; END IF;
 IF (SELECT count(*) FROM api_next.schema_migrations)<>333
 OR (SELECT encode(sha256(convert_to(string_agg(version||':'||checksum,E'\n' ORDER BY version),'UTF8')),'hex') FROM api_next.schema_migrations)
 IS DISTINCT FROM '95cdd12cfef6dc5eaf89d0e7734b1d692477c12d621f2596d923ad3499a94280' THEN RAISE EXCEPTION 'Browser release ledger differs'; END IF;
 FOR signature IN SELECT unnest(ARRAY['create_browser_session_v1(jsonb)','read_browser_session_access_v1(text,text,text)','read_browser_session_renewal_v1(text,text,text,text)','renew_browser_session_v1(text,text,text,text)','revoke_browser_session_v1(text,text,text,text,text)']::text[]) LOOP
  SELECT p.* INTO fn FROM pg_catalog.pg_proc p
  WHERE p.oid=pg_catalog.to_regprocedure('"api_next".'||signature);
  IF fn.oid IS NULL OR fn.pronamespace<>ns OR fn.proowner<>owner_id OR NOT fn.prosecdef
  OR fn.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog, api_next, pg_temp']
  OR EXISTS(SELECT 1 FROM pg_catalog.aclexplode(COALESCE(fn.proacl,pg_catalog.acldefault('f',fn.proowner))) acl WHERE acl.grantee=0 AND acl.privilege_type='EXECUTE')
  OR pg_catalog.has_function_privilege(target,fn.oid,'EXECUTE') IS DISTINCT FROM false
  THEN RAISE EXCEPTION 'Browser release function boundary differs: %',signature; END IF;
 END LOOP;
 IF pg_catalog.has_table_privilege(target,'api_next.browser_sessions','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
 OR pg_catalog.has_any_column_privilege(target,'api_next.browser_sessions','SELECT,INSERT,UPDATE,REFERENCES')
 THEN RAISE EXCEPTION 'Browser release private table access differs'; END IF;
END $browser_release$

